export const SS14_OFFENSE_RULES = {"season":"SS14","releaseVerified":false,"generatedAt":"2026-10-15T12:56:03.585Z","pages":{"en/Critical_Strike":{"sourceUrl":"https://tlidb.com/en/Critical_Strike","sourcePageSha256":"019e6c6696225bbb128f4ec8a2a884ecc351acdee031991fe56a8a26ac458b16","locale":"en","slug":"Critical_Strike","title":"Critical Strike","body":"There is a chance to deal a Critical Strike when dealing Hit Damage.\nThere is a chance to deal a Critical Strike when dealing damage. If a skill can deal damage more than once (such as Spiral Strike), the Critical Strike determination is usually only carried out once.\nCritical Strike Rating\nWhen attacking, the base Critical Strike Rating of the weapon will be factored in when calculating the Critical Strike Rating of the skill. When casting a spell, the base Critical Strike Rating of the spell will be factored in when calculating the Critical Strike Rating of the skill.\nFinal Critical Strike Rating = The sum of Base Critical Strike Rating x (1 + all non-additional bonus percentages) x (1 + additional bonus percentage 1) x (1 + additional bonus percentage 2)...\nCritical Hit Chance = Final Critical Strike Rating/100.\nCritical Strike Damage\nAll units have 150% Critical Strike Damage by default.\nWhen dealing a Critical Strike, the damage dealt by the hit becomes: The original damage x the Critical Strike Damage percentage.","season":"SS14","authorityScope":"preview-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"f0d2c8f9eb6328cad28f7b3c08ddc747262d2e3daef435cc2c74e54768967f9e"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Fire_Burst","sourcePageSha256":"9885acf1a8d5e5dd37de413bd59f7e4699e58b8ce4912822c0696cdc5b792f31"}},"en/Lucky":{"sourceUrl":"https://tlidb.com/en/Lucky","sourcePageSha256":"923c024ecbf4b283588e8008d82e19e464e48246c918e5333cbc2e43cc2055e8","locale":"en","slug":"Lucky","title":"Lucky","body":"Performs a random check or random roll twice and picks the result that benefits you the most\n\nCertain random results in combat are affected by Luck: When Lucky, the result is rolled multiple times and the more favorable one is kept. When Unlucky, the less favorable one is kept. The two effects can cancel each other out.\nLucky & Unlucky\nCertain random results in combat (such as damage rolls, Critical Strikes, Blocking, Evading and more) are affected by Lucky and Unlucky. They take effect by changing the number of rolls for the result:\nLucky: The result is rolled twice, and the more favorable one is kept.\nVery Lucky: The result is rolled three times, and the most favorable one is kept.\nUnlucky: The result is rolled twice, and the less favorable one is kept.\nWhen Lucky and Unlucky are both present, they cancel each other out. When Very Lucky and Unlucky are both present, they cancel into Lucky.","season":"SS14","authorityScope":"preview-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/en/","sourcePageSha256":"f0d2c8f9eb6328cad28f7b3c08ddc747262d2e3daef435cc2c74e54768967f9e"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/en/Fire_Burst","sourcePageSha256":"9885acf1a8d5e5dd37de413bd59f7e4699e58b8ce4912822c0696cdc5b792f31"}},"ko/Critical_Strike":{"sourceUrl":"https://tlidb.com/ko/Critical_Strike","sourcePageSha256":"b9756a7e9e8491a579f240aa31ae381c39240cce83f73d94a6e0d2a64283ac6b","locale":"ko","slug":"Critical_Strike","title":"Critical Strike","body":"적중 대미지를 입힐 때, 일정 확률로 크리티컬이 발동됩니다.\n적중 대미지를 입힐 때 일정 확률로 크리티컬이 발동됩니다. 스킬 한 번으로 여러번 적중 시(예: 나선 공격), 종종 크리티컬 1회로 판정됩니다.\n크리티컬\n공격 시, 무기의 기본 크리티컬이 해당 스킬의 크리티컬 계산에 관여합니다. 시전 시, 주술의 기본 크리티컬이 해당 스킬의 크리티컬 계산에 관여합니다.\n최종 크리티컬=기본 크리티컬의 합*(1+모든 비추가 비율 보너스)*(1+추가 비율 보너스1)*(1+추가 비율 보너스2)...\n크리티컬의 확률=최종 크리티컬/100\n크리티컬 대미지\n모든 유닛은 기본 150%의 크리티컬 대미지를 보유합니다.\n크리티컬 시, 해당 회차의 적중으로 주는 대미지가 원래의 대미지*크리티컬 대미지 비율로 증가합니다.","season":"SS14","authorityScope":"preview-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"13fae8e850f7f3a290f38f6459e2e4a99f058890fe4a7c9b6950102b7f83f6fc"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Fire_Burst","sourcePageSha256":"17e223e3ac676cf2405e1ff08fc22238d94986a4064c61d6b3c4cccc2ef1b7fc"}},"ko/Lucky":{"sourceUrl":"https://tlidb.com/ko/Lucky","sourcePageSha256":"4f487aa8db07d308b662df87dcc3010e7c7f814477868e2649070e2c949a0f8c","locale":"ko","slug":"Lucky","title":"Lucky","body":"두 번의 랜덤 판정 또는 수치 중 가장 유리한 결과 적용\n\n전투 중 일부 무작위 결과는 행운의 영향을 받습니다. 행운 시 해당 결과는 여러 번 판정되어 더 유리한 결과를 유지하고, 불행 시 더 불리한 결과를 유지하며, 둘은 서로 상쇄될 수 있습니다.\n행운과 불행\n전투 중 일부 무작위 결과(예: 대미지 수치, 크리티컬, 막기, 회피 등)는 행운과 불행의 영향을 받으며, 결과의 판정 횟수를 변경하여 적용됩니다.\n· 행운: 해당 결과를 두 번 판정하여, 더 유리한 결과를 유지합니다.\n· 슈퍼 행운: 해당 결과를 세 번 판정하여, 가장 유리한 결과를 유지합니다.\n· 불행: 해당 결과를 두 번 판정하여, 더 불리한 결과를 유지합니다.\n행운과 불행이 동시에 존재할 경우 서로 상쇄됩니다. 슈퍼 행운과 불행이 동시에 존재할 경우 상쇄되어 행운이 됩니다.","season":"SS14","authorityScope":"preview-site-deployment","rootReceipt":{"sourceUrl":"https://tlidb.com/ko/","sourcePageSha256":"13fae8e850f7f3a290f38f6459e2e4a99f058890fe4a7c9b6950102b7f83f6fc"},"anchorReceipt":{"sourceUrl":"https://tlidb.com/ko/Fire_Burst","sourcePageSha256":"17e223e3ac676cf2405e1ff08fc22238d94986a4064c61d6b3c4cccc2ef1b7fc"}}}};
